#!/usr/bin/env bash
# Build both .wgt packages: the launcher and the Home-key wrapper.
# Inlines the shared app catalog (../apps.json) into the launcher bundle.
set -euo pipefail
cd "$(dirname "$0")"

python3 - <<'PY'
import json, os
apps = json.load(open('../apps.json'))
extra_path = '../apps-extra.json'
extra = json.load(open(extra_path)) if os.path.exists(extra_path) else []
open('launcher/js/catalog.js', 'w').write(
    '/* generated by build.sh from ../apps.json and ../apps-extra.json */\n'
    'var CATALOG = %s;\n'
    'var CATALOG_EXTRA = %s;\n'
    % (json.dumps(apps, ensure_ascii=False, indent=2),
       json.dumps(extra, ensure_ascii=False, indent=2)))
PY

cd launcher
rm -f ../freshhome-launcher.wgt
zip -X -q ../freshhome-launcher.wgt config.xml index.html css/style.css js/app.js js/catalog.js js/input.js games/snake.html games/breakout.html games/g2048.html

cd ../homekey
rm -f ../freshhome-homekey.wgt
zip -X -q ../freshhome-homekey.wgt config.xml index.html

echo "built: freshhome-launcher.wgt, freshhome-homekey.wgt"
